const dateUtils = require('./dateUtils');

describe('dateUtils', () => {
  describe('formatDate', () => {
    it('should format a valid date', () => {
      const date = new Date('2022-01-01T00:00:00.000Z');
      const expected = '2022-01-01';
      expect(dateUtils.formatDate(date)).toBe(expected);
    });

    it('should format a date with single digit month', () => {
      const date = new Date('2022-09-01T00:00:00.000Z');
      const expected = '2022-09-01';
      expect(dateUtils.formatDate(date)).toBe(expected);
    });

    it('should format a date with single digit day', () => {
      const date = new Date('2022-01-09T00:00:00.000Z');
      const expected = '2022-01-09';
      expect(dateUtils.formatDate(date)).toBe(expected);
    });

    it('should format a date with month and day greater than 9', () => {
      const date = new Date('2022-12-31T00:00:00.000Z');
      const expected = '2022-12-31';
      expect(dateUtils.formatDate(date)).toBe(expected);
    });

    it('should handle dates in different time zones', () => {
      const date = new Date('2022-01-01T00:00:00-05:00');
      const expected = '2022-01-01';
      expect(dateUtils.formatDate(date)).toBe(expected);
    });

    it('should handle dates with milliseconds', () => {
      const date = new Date('2022-01-01T00:00:00.123Z');
      const expected = '2022-01-01';
      expect(dateUtils.formatDate(date)).toBe(expected);
    });

    it('should handle string dates', () => {
      const date = '2022-01-01T00:00:00.000Z';
      const expected = '2022-01-01';
      expect(dateUtils.formatDate(date)).toBe(expected);
    });

    it('should handle number dates (timestamps)', () => {
      const date = 1640995200000; // January 1, 2022, 00:00:00 UTC
      const expected = '2022-01-01';
      expect(dateUtils.formatDate(date)).toBe(expected);
    });
  });
});

