import static org.junit.jupiter.api.Assertions.*;

public class StringUtilsTest {

    @Test
    public void testReverse_NullInput() {
        // Given
        String input = null;

        // When
        String result = StringUtils.reverse(input);

        // Then
        assertNull(result);
    }

    @Test
    public void testReverse_SingleCharacter() {
        // Given
        String input = "a";

        // When
        String result = StringUtils.reverse(input);

        // Then
        assertEquals("a", result);
    }

    @Test
    public void testReverse_MultipleCharacters() {
        // Given
        String input = "hello";

        // When
        String result = StringUtils.reverse(input);

        // Then
        assertEquals("olleh", result);
    }

    @Test
    public void testIsPalindrome_NullInput() {
        // Given
        String input = null;

        // When
        boolean result = StringUtils.isPalindrome(input);

        // Then
        assertFalse(result);
    }

    @Test
    public void testIsPalindrome_SingleCharacter() {
        // Given
        String input = "a";

        // When
        boolean result = StringUtils.isPalindrome(input);

        // Then
        assertTrue(result);
    }

    @Test
    public void testIsPalindrome_Palindrome() {
        // Given
        String input = "madam";

        // When
        boolean result = StringUtils.isPalindrome(input);

        // Then
        assertTrue(result);
    }

    @Test
    public void testIsPalindrome_NotPalindrome() {
        // Given
        String input = "hello";

        // When
        boolean result = StringUtils.isPalindrome(input);

        // Then
        assertFalse(result);
    }

    @Test
    public void testIsPalindrome_IgnoringCase() {
        // Given
        String input = "MaDaM";

        // When
        boolean result = StringUtils.isPalindrome(input);

        // Then
        assertTrue(result);
    }
}

