import { Calculator } from './Calculator';

describe('Calculator', () => {
    let calculator: Calculator;

    beforeEach(() => {
        calculator = new Calculator();
    });

    describe('add', () => {
        it('should add two positive numbers', () => {
            const result = calculator.add(5, 7);
            expect(result).toBe(12);
        });

        it('should add two negative numbers', () => {
            const result = calculator.add(-5, -7);
            expect(result).toBe(-12);
        });

        it('should add a positive and a negative number', () => {
            const result = calculator.add(5, -7);
            expect(result).toBe(-2);
        });

        it('should add a number and zero', () => {
            const result = calculator.add(5, 0);
            expect(result).toBe(5);
        });
    });

    describe('subtract', () => {
        it('should subtract two positive numbers', () => {
            const result = calculator.subtract(10, 7);
            expect(result).toBe(3);
        });

        it('should subtract two negative numbers', () => {
            const result = calculator.subtract(-10, -7);
            expect(result).toBe(-3);
        });

        it('should subtract a positive and a negative number', () => {
            const result = calculator.subtract(10, -7);
            expect(result).toBe(17);
        });

        it('should subtract a number and zero', () => {
            const result = calculator.subtract(10, 0);
            expect(result).toBe(10);
        });
    });

    describe('multiply', () => {
        it('should multiply two positive numbers', () => {
            const result = calculator.multiply(5, 7);
            expect(result).toBe(35);
        });

        it('should multiply two negative numbers', () => {
            const result = calculator.multiply(-5, -7);
            expect(result).toBe(35);
        });

        it('should multiply a positive and a negative number', () => {
            const result = calculator.multiply(5, -7);
            expect(result).toBe(-35);
        });

        it('should multiply a number and zero', () => {
            const result = calculator.multiply(5, 0);
            expect(result).toBe(0);
        });
    });

    describe('divide', () => {
        it('should divide two positive numbers', () => {
            const result = calculator.divide(10, 2);
            expect(result).toBe(5);
        });

        it('should divide two negative numbers', () => {
            const result = calculator.divide(-10, -2);
            expect(result).toBe(5);
        });

        it('should divide a positive and a negative number', () => {
            const result = calculator.divide(10, -2);
            expect(result).toBe(-5);
        });

        it('should throw an error when dividing by zero', () => {
            expect(() => calculator.divide(10, 0)).toThrowError('Cannot divide by zero');
        });
    });
});
